DO $migration$ DECLARE body text;BEGIN SELECT pg_get_functiondef('public.post_stock_operation(uuid,uuid,uuid,uuid,uuid,text,numeric,text,text)'::regprocedure) INTO body;body:=replace(body,'SELECT coalesce(sum(quantity),0) INTO balance FROM public.stock_movements WHERE business_id=_business_id AND branch_id=_branch_id AND variant_id=_variant_id;','SELECT public.commerce_stock_balance(_business_id,_branch_id,_variant_id) INTO balance;');EXECUTE body;END $migration$;
CREATE FUNCTION public.guard_commerce_payload() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l jsonb;BEGIN IF NEW.status='confirmed' AND NEW.source_id IS NOT NULL AND NEW.kind='purchase' AND EXISTS(SELECT 1 FROM public.commerce_documents WHERE id=NEW.source_id AND kind='purchase_order') THEN FOR l IN SELECT value FROM jsonb_array_elements(NEW.lines) LOOP IF NOT EXISTS(SELECT 1 FROM public.commerce_documents d CROSS JOIN LATERAL jsonb_array_elements(d.lines) s WHERE d.id=NEW.source_id AND s->>'variantId'=l->>'variantId') THEN RAISE EXCEPTION 'Purchase line absent from order';END IF;END LOOP;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.guard_commerce_payload() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER commerce_payload_guard BEFORE INSERT ON public.commerce_documents FOR EACH ROW EXECUTE FUNCTION public.guard_commerce_payload();